import React from 'react';
import { Box, Typography, Button } from '@mui/material';

function CustomCard({ title, description, tags, buttonText, imageUrl }) {
  return (
    <Box
      sx={{
        width: '328px',
        height: '380px', // Daha kompakt bir kart boyutu
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-start', // Başlık ve açıklamanın yukarıda olması için
        alignItems: 'center',
        padding: '16px', // Padding'i artırarak içeriği rahatlatıyoruz
        backgroundColor: '#FFFFFF',
        borderRadius: '16px',
        boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.1)', // Gölgeleme ekledik
        boxSizing: 'border-box',
        marginBottom: '16px', // Kartlar arasına boşluk eklemek için
      }}
    >
      {/* Kartın üst kısmındaki görsel */}
      <Box
        sx={{
          width: '100%',
          height: '160px', // Görsel boyutunu ayarladık
          backgroundImage: `url(${imageUrl})`,
          backgroundSize: 'cover', // Görseli kapsayacak şekilde yerleştir
          backgroundPosition: 'center',
          borderRadius: '8px',
          marginBottom: '12px', // Görsel ile metin arasına boşluk ekledik
        }}
      />

      {/* Başlık ve açıklama */}
      <Box sx={{ width: '100%', textAlign: 'center', marginBottom: '16px' }}>
        <Typography variant="h6" sx={{ fontWeight: '600', fontSize: '18px', color: '#1D1D1D' }}>
          {title}
        </Typography>
        <Typography sx={{ fontSize: '14px', color: '#878787', marginTop: '8px' }}>
          {description}
        </Typography>
      </Box>

      {/* Etiketler */}
      <Box sx={{ display: 'flex', justifyContent: 'center', gap: '8px', marginBottom: '12px' }}>
        {tags.map((tag, index) => (
          <Box
            key={index}
            sx={{
              padding: '4px 12px',
              backgroundColor: '#F6F8FF',
              borderRadius: '20px',
              border: '1px solid #D1D5DB',
            }}
          >
            <Typography sx={{ fontSize: '12px', color: '#293349' }}>
              {tag}
            </Typography>
          </Box>
        ))}
      </Box>

      {/* Başvuru düğmesi */}
      <Box sx={{ width: '100%' }}>
        <Button
          variant="contained"
          sx={{
            width: '100%',
            padding: '12px',
            backgroundColor: '#00C26D',
            color: '#FFFFFF',
            fontSize: '16px',
            fontWeight: '500',
            borderRadius: '8px',
            textTransform: 'none',
          }}
        >
          {buttonText}
        </Button>
      </Box>
    </Box>
  );
}

export default CustomCard;
